import numpy as np

def f(a):
    try:
        inner1 = np.floor(22 * a)
        inner2 = np.floor(22 * a * inner1)
        inner3 = np.floor(22 * a * inner2)
        return a * inner3
    except:
        return None

# Search for solutions in a range
solutions = []
for a_val in np.linspace(-1, 1, 100000):
    if f(a_val) == 4:
        solutions.append(a_val)

print(f"Solutions found in range [-1, 1]: {solutions}")
